'use strict';
/*
 * Шёпот — сервер мессенджера со сквозным шифрованием.
 *
 * Сервер ничего не может прочитать: он получает только зашифрованные
 * строки и пересылает их всем, кто подключён к той же комнате.
 * Ключ комнаты живёт в части ссылки после "#", а она никогда не
 * отправляется на сервер.
 *
 * Без зависимостей: только встроенные модули Node.js (нужен Node 18+).
 */
const http = require('http');
const https = require('https');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

const PORT = Number(process.env.PORT) || 8080;
const HOST = process.env.HOST || '0.0.0.0';
// На Render (и подобных хостингах) все запросы приходят через их прокси —
// настоящий адрес клиента лежит в X-Forwarded-For. Иначе защита от флуда
// считала бы всех пользователей одним человеком.
const ON_HOSTING = Boolean(process.env.RENDER);
const TRUST_PROXY = process.env.TRUST_PROXY === '1' || ON_HOSTING;
const PUBLIC_DIR = path.join(__dirname, 'public');
const PFX_PATH = path.join(__dirname, 'cert', 'shepot.pfx');
const PASS_PATH = path.join(__dirname, 'cert', 'pass.txt');

const LIMITS = {
  bodyBytes: 2_000_000, // максимальный размер запроса (картинка ~700 КБ после шифрования)
  dataChars: 1_900_000, // максимальная длина зашифрованной строки
  historyPerRoom: 100, // сколько последних сообщений помнить
  historyTtlMs: 24 * 60 * 60 * 1000, // и не дольше суток
  historyBytesPerRoom: 20_000_000,
  rooms: 2000,
  subsPerRoom: 64,
  streamsPerIp: 16,
  postsPerWindow: 60, // звонки при соединении шлют пачку служебных сообщений
  windowMs: 10_000,
};

// ---------- Push-уведомления (Web Push, RFC 8291 + VAPID RFC 8292) ----------
// Сервер не хранит подписки: отправитель сообщения сам присылает список устройств
// участников комнаты, которым нужно «постучаться». В уведомлении нет текста —
// только «новое сообщение» или «звонок», зашифрованные ключом устройства.
const b64u = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const b64uDecode = (s) => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
const VAPID_PUBLIC = (process.env.VAPID_PUBLIC || '').trim();
const VAPID_SUBJECT = process.env.VAPID_SUBJECT || 'https://shepot.onrender.com';
const PUSH_HOST_RE = /(^|\.)(fcm\.googleapis\.com|android\.googleapis\.com|push\.services\.mozilla\.com|notify\.windows\.com|push\.apple\.com)$/;
let vapidKey = null;
if (VAPID_PUBLIC && process.env.VAPID_PRIVATE) {
  try {
    const pub = b64uDecode(VAPID_PUBLIC);
    if (pub.length !== 65 || pub[0] !== 4) throw new Error('bad public key');
    vapidKey = crypto.createPrivateKey({
      key: { kty: 'EC', crv: 'P-256', d: process.env.VAPID_PRIVATE.trim(), x: b64u(pub.subarray(1, 33)), y: b64u(pub.subarray(33)) },
      format: 'jwk',
    });
  } catch (e) {
    console.error('  ⚠ VAPID-ключи неверные — push-уведомления выключены:', e.message);
    vapidKey = null;
  }
}

function hkdf(salt, ikm, info, len) {
  const prk = crypto.createHmac('sha256', salt).update(ikm).digest();
  return crypto.createHmac('sha256', prk).update(Buffer.concat([info, Buffer.from([1])])).digest().subarray(0, len);
}

function encryptPush(payload, p256dh, auth, opts = {}) {
  const uaPub = b64uDecode(p256dh);
  const authSecret = b64uDecode(auth);
  if (uaPub.length !== 65 || authSecret.length !== 16) throw new Error('bad subscription keys');
  const ecdh = crypto.createECDH('prime256v1');
  if (opts.asPrivate) ecdh.setPrivateKey(opts.asPrivate);
  else ecdh.generateKeys();
  const asPub = ecdh.getPublicKey();
  const shared = ecdh.computeSecret(uaPub);
  const ikm = hkdf(authSecret, shared, Buffer.concat([Buffer.from('WebPush: info\0'), uaPub, asPub]), 32);
  const salt = opts.salt || crypto.randomBytes(16);
  const cek = hkdf(salt, ikm, Buffer.from('Content-Encoding: aes128gcm\0'), 16);
  const nonce = hkdf(salt, ikm, Buffer.from('Content-Encoding: nonce\0'), 12);
  const cipher = crypto.createCipheriv('aes-128-gcm', cek, nonce);
  const ct = Buffer.concat([cipher.update(Buffer.concat([payload, Buffer.from([2])])), cipher.final(), cipher.getAuthTag()]);
  const header = Buffer.alloc(21);
  salt.copy(header, 0);
  header.writeUInt32BE(4096, 16);
  header[20] = asPub.length;
  return Buffer.concat([header, asPub, ct]);
}

function vapidHeader(endpoint) {
  const enc = (o) => b64u(Buffer.from(JSON.stringify(o)));
  const data = `${enc({ typ: 'JWT', alg: 'ES256' })}.${enc({
    aud: new URL(endpoint).origin,
    exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: VAPID_SUBJECT,
  })}`;
  const sig = crypto.sign('sha256', Buffer.from(data), { key: vapidKey, dsaEncoding: 'ieee-p1363' });
  return `vapid t=${data}.${b64u(sig)}, k=${VAPID_PUBLIC}`;
}

function validSub(s) {
  if (!s || typeof s !== 'object' || typeof s.endpoint !== 'string' || s.endpoint.length > 800) return false;
  if (!s.keys || typeof s.keys.p256dh !== 'string' || typeof s.keys.auth !== 'string') return false;
  if (s.keys.p256dh.length > 120 || s.keys.auth.length > 40) return false;
  try {
    const u = new URL(s.endpoint);
    return u.protocol === 'https:' && PUSH_HOST_RE.test(u.hostname); // только настоящие push-сервисы
  } catch {
    return false;
  }
}

function sendPush(sub, obj) {
  return new Promise((resolve) => {
    if (!vapidKey) return resolve({ status: 0, error: 'на сервере не настроены VAPID-ключи' });
    if (!validSub(sub)) return resolve({ status: 0, error: 'неподходящий адрес push-сервиса' });
    let body;
    try {
      body = encryptPush(Buffer.from(JSON.stringify(obj)), sub.keys.p256dh, sub.keys.auth);
    } catch (e) {
      return resolve({ status: 0, error: 'не удалось зашифровать: ' + e.message });
    }
    sendPushRaw(sub, obj, body, resolve);
  });
}

function sendPushRaw(sub, obj, body, done) {
  const headers = {
    'Content-Encoding': 'aes128gcm',
    'Content-Type': 'application/octet-stream',
    'Content-Length': body.length,
    TTL: obj.k === 'call' || obj.k === 'end' ? '60' : String(24 * 3600),
    Urgency: 'high',
    Authorization: vapidHeader(sub.endpoint),
  };
  if (obj.k === 'msg') headers.Topic = 'm' + String(obj.r).slice(0, 24); // несколько сообщений схлопываются в одно уведомление
  const host = new URL(sub.endpoint).hostname;
  const req = https.request(sub.endpoint, { method: 'POST', headers, timeout: 10000 }, (res) => {
    let text = '';
    res.setEncoding('utf8');
    res.on('data', (c) => {
      if (text.length < 500) text += c;
    });
    res.on('end', () => {
      // В логах только сервис и код ответа — без адресов устройств
      console.log(`push ${obj.k} → ${host}: ${res.statusCode}${res.statusCode >= 300 ? ' ' + text.slice(0, 200).replace(/\s+/g, ' ') : ''}`);
      done({ status: res.statusCode, body: text.slice(0, 300) });
    });
  });
  req.on('timeout', () => req.destroy(new Error('timeout')));
  req.on('error', (e) => {
    console.log(`push ${obj.k} → ${host}: ошибка ${e.message}`);
    done({ status: 0, error: e.message });
  });
  req.end(body);
}

const pushCooldown = new Map(); // устройство -> время последнего уведомления
function pushAllowed(dev, kind) {
  const now = Date.now();
  const key = dev + ':' + kind;
  const last = pushCooldown.get(key) || 0;
  const gap = kind === 'call' ? 3000 : kind === 'end' ? 0 : 15000;
  if (now - last < gap) return false;
  pushCooldown.set(key, now);
  return true;
}

// Самопроверка шифрования по официальному примеру из RFC 8291: SHEPOT_SELFTEST=1 node server.js
if (process.env.SHEPOT_SELFTEST === '1') {
  const out = encryptPush(Buffer.from('When I grow up, I want to be a watermelon'), 'BCVxsr7N_eNgVRqvHtD0zTZsEc6-VV-JvLexhqUzORcxaOzi6-AYWXvTBHm4bjyPjs7Vd8pZGH6SRpkNtoIAiw4', 'BTBZMqHH6r4Tts7J_aSIgg', {
    asPrivate: b64uDecode('yfWPiYE-n46HLnH0KqZOF1fJJU3MYrct3AELtAQ-oRw'),
    salt: b64uDecode('DGv6ra1nlYgDCS1FRnbzlw'),
  });
  const expected =
    'DGv6ra1nlYgDCS1FRnbzlwAAEABBBP4z9KsN6nGRTbVYI_c7VJSPQTBtkgcy27mlmlMoZIIgDll6e3vCYLocInmYWAmS6TlzAC8wEqKK6PBru3jl7A_yl95bQpu6cVPTpK4Mqgkf1CXztLVBSt2Ks3oZwbuwXPXLWyouBWLVWGNWQexSgSxsj_Qulcy4a-fN';
  const ok = b64u(out) === expected;
  console.log(ok ? 'RFC8291 OK' : 'RFC8291 MISMATCH ' + b64u(out));
  process.exit(ok ? 0 : 1);
}

// Генерация ключей: node server.js --gen-vapid
if (process.argv.includes('--gen-vapid')) {
  const ecdh = crypto.createECDH('prime256v1');
  ecdh.generateKeys();
  console.log('VAPID_PUBLIC=' + b64u(ecdh.getPublicKey()));
  const d = Buffer.alloc(32);
  const raw = ecdh.getPrivateKey();
  raw.copy(d, 32 - raw.length);
  console.log('VAPID_PRIVATE=' + b64u(d));
  process.exit(0);
}

// Уникальный номер запуска: после перезапуска старые номера сообщений недействительны.
const BOOT = crypto.randomBytes(4).toString('hex');

const ROOM_RE = /^[a-f0-9]{32}$/;
const DEV_RE = /^[A-Za-z0-9_-]{8,40}$/;
const DATA_RE = /^[A-Za-z0-9_-]+$/;

/** @type {Map<string, {subs:Set<import('http').ServerResponse>, history:{seq:number,data:string,ts:number}[], seq:number, bytes:number}>} */
const rooms = new Map();
const postCounters = new Map(); // ip -> {count, reset}
const streamCounters = new Map(); // ip -> число открытых потоков

const STATIC = {
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/index.html': ['index.html', 'text/html; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
  '/style.css': ['style.css', 'text/css; charset=utf-8'],
  '/favicon.svg': ['favicon.svg', 'image/svg+xml'],
  '/manifest.webmanifest': ['manifest.webmanifest', 'application/manifest+json; charset=utf-8'],
  '/sw.js': ['sw.js', 'text/javascript; charset=utf-8'],
  '/icon-192.png': ['icon-192.png', 'image/png'],
  '/icon-512.png': ['icon-512.png', 'image/png'],
  '/icon-maskable.png': ['icon-maskable.png', 'image/png'],
  '/apple-touch-icon.png': ['apple-touch-icon.png', 'image/png'],
  '/badge-96.png': ['badge-96.png', 'image/png'],
};
const staticCache = new Map();
// Файлы интерфейса ищем в public/, а если их туда не положили (например, при загрузке
// на GitHub папка «расплющилась») — рядом с server.js.
function findStatic(name) {
  for (const dir of [PUBLIC_DIR, __dirname]) {
    const file = path.join(dir, name);
    if (fs.existsSync(file)) return file;
  }
  return null;
}
// В «однофайловой» сборке (build-single.js) сюда встраиваются файлы интерфейса.
const EMBEDDED = {"badge-96.png":"","style.css":"","app.js":"","sw.js":"","favicon.svg":"","index.html":"","icon-512.png":"","icon-192.png":"","icon-maskable.png":"","apple-touch-icon.png":"","manifest.webmanifest":""};

function loadStatic(name) {
  if (process.env.NODE_ENV === 'production' && staticCache.has(name)) return staticCache.get(name);
  const file = findStatic(name);
  if (!file) {
    if (EMBEDDED && typeof EMBEDDED[name] === 'string') return Buffer.from(EMBEDDED[name], 'base64');
    throw new Error('missing ' + name);
  }
  const body = fs.readFileSync(file);
  if (process.env.NODE_ENV === 'production') staticCache.set(name, body);
  return body;
}
const missingStatic = [...new Set(Object.values(STATIC).map((e) => e[0]))].filter(
  (n) => !findStatic(n) && !(EMBEDDED && EMBEDDED[n])
);
if (missingStatic.length) {
  console.error(`\n  ❌ Не найдены файлы интерфейса: ${missingStatic.join(', ')}`);
  console.error('     Положи их в папку public/ рядом с server.js (или прямо рядом с server.js).\n');
}

let useHttps = false;

function securityHeaders(res) {
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' blob: data:; " +
      "connect-src 'self'; media-src 'self' blob:; manifest-src 'self'; worker-src 'self'; " +
      "base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
  );
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('Cross-Origin-Opener-Policy', 'same-origin');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
  res.setHeader('Permissions-Policy', 'camera=(self), microphone=(self), geolocation=(), interest-cohort=()');
  res.setHeader('Cache-Control', 'no-store');
  if (useHttps) res.setHeader('Strict-Transport-Security', 'max-age=31536000');
}

function clientIp(req) {
  if (TRUST_PROXY) {
    const fwd = req.headers['x-forwarded-for'];
    if (typeof fwd === 'string' && fwd) return fwd.split(',')[0].trim();
  }
  return req.socket.remoteAddress || 'unknown';
}

function sendJson(res, status, obj) {
  if (res.headersSent) return;
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(obj));
}

function getRoom(id, create) {
  let room = rooms.get(id);
  if (!room && create) {
    if (rooms.size >= LIMITS.rooms) return null;
    room = { subs: new Set(), history: [], seq: 0, bytes: 0, devs: new Map() };
    rooms.set(id, room);
  }
  return room || null;
}

function sseWrite(res, event, data, id) {
  let chunk = '';
  if (id) chunk += `id: ${id}\n`;
  chunk += `event: ${event}\ndata: ${data}\n\n`;
  res.write(chunk);
}

function broadcastPresence(room) {
  const payload = JSON.stringify({ online: room.subs.size });
  for (const sub of room.subs) sseWrite(sub, 'presence', payload);
}

function sameOrigin(req) {
  const origin = req.headers.origin;
  if (!origin) return true; // не браузер или тот же сайт без заголовка
  try {
    return new URL(origin).host === req.headers.host;
  } catch {
    return false;
  }
}

function rateLimited(ip) {
  const now = Date.now();
  let c = postCounters.get(ip);
  if (!c || now > c.reset) {
    c = { count: 0, reset: now + LIMITS.windowMs };
    postCounters.set(ip, c);
  }
  c.count++;
  return c.count > LIMITS.postsPerWindow;
}

function handleEvents(req, res, url) {
  const roomId = url.searchParams.get('room') || '';
  if (!ROOM_RE.test(roomId)) return sendJson(res, 400, { error: 'bad room' });

  const ip = clientIp(req);
  const open = streamCounters.get(ip) || 0;
  if (open >= LIMITS.streamsPerIp) return sendJson(res, 429, { error: 'too many connections' });

  const room = getRoom(roomId, true);
  if (!room) return sendJson(res, 503, { error: 'server full' });
  if (room.subs.size >= LIMITS.subsPerRoom) return sendJson(res, 503, { error: 'room full' });

  res.writeHead(200, {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-store',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.write('retry: 2000\n\n');

  // История: отдаём то, что клиент ещё не видел (после переподключения).
  let after = 0;
  const lastId = req.headers['last-event-id'];
  if (typeof lastId === 'string') {
    const [boot, seq] = lastId.split('-');
    if (boot === BOOT && /^\d+$/.test(seq || '')) after = Number(seq);
  }
  for (const m of room.history) {
    if (m.seq > after) sseWrite(res, 'msg', JSON.stringify({ data: m.data }), `${BOOT}-${m.seq}`);
  }
  sseWrite(res, 'ready', '{}');

  room.subs.add(res);
  streamCounters.set(ip, open + 1);
  // Устройство онлайн — ему не нужен push, оно и так получит сообщение
  const dev = url.searchParams.get('dev') || '';
  const devOk = DEV_RE.test(dev);
  if (devOk) room.devs.set(dev, (room.devs.get(dev) || 0) + 1);
  broadcastPresence(room);

  const ping = setInterval(() => res.write(': ping\n\n'), 20_000);
  let closed = false;
  const cleanup = () => {
    if (closed) return;
    closed = true;
    clearInterval(ping);
    room.subs.delete(res);
    if (devOk) {
      const c = (room.devs.get(dev) || 1) - 1;
      if (c <= 0) room.devs.delete(dev);
      else room.devs.set(dev, c);
    }
    const n = (streamCounters.get(ip) || 1) - 1;
    if (n <= 0) streamCounters.delete(ip);
    else streamCounters.set(ip, n);
    broadcastPresence(room);
  };
  req.on('close', cleanup);
  res.on('close', cleanup);
  res.on('error', cleanup);
}

function handleSend(req, res) {
  if (!sameOrigin(req)) return sendJson(res, 403, { error: 'forbidden' });
  const ctype = String(req.headers['content-type'] || '');
  if (!ctype.startsWith('application/json')) return sendJson(res, 415, { error: 'json only' });
  if (rateLimited(clientIp(req))) return sendJson(res, 429, { error: 'slow down' });

  const declared = Number(req.headers['content-length'] || 0);
  if (declared > LIMITS.bodyBytes) {
    sendJson(res, 413, { error: 'too large' });
    req.resume();
    return;
  }

  const chunks = [];
  let size = 0;
  let aborted = false;
  req.on('data', (c) => {
    if (aborted) return;
    size += c.length;
    if (size > LIMITS.bodyBytes) {
      aborted = true;
      sendJson(res, 413, { error: 'too large' });
      return;
    }
    chunks.push(c);
  });
  req.on('end', () => {
    if (aborted) return;
    let body;
    try {
      body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    } catch {
      return sendJson(res, 400, { error: 'bad json' });
    }
    if (!body || typeof body !== 'object') return sendJson(res, 400, { error: 'bad body' });
    const { room: roomId, data, store, push } = body;
    if (typeof roomId !== 'string' || !ROOM_RE.test(roomId)) return sendJson(res, 400, { error: 'bad room' });
    if (typeof data !== 'string' || data.length < 40 || data.length > LIMITS.dataChars || !DATA_RE.test(data)) {
      return sendJson(res, 400, { error: 'bad data' });
    }

    const room = getRoom(roomId, true);
    if (!room) return sendJson(res, 503, { error: 'server full' });

    const payload = JSON.stringify({ data });
    if (store === false) {
      // Эфемерное: «печатает…», исчезающие сообщения — не сохраняем.
      for (const sub of room.subs) sseWrite(sub, 'msg', payload);
    } else {
      const seq = ++room.seq;
      room.history.push({ seq, data, ts: Date.now() });
      room.bytes += data.length;
      while (room.history.length > LIMITS.historyPerRoom || room.bytes > LIMITS.historyBytesPerRoom) {
        room.bytes -= room.history.shift().data.length;
      }
      for (const sub of room.subs) sseWrite(sub, 'msg', payload, `${BOOT}-${seq}`);
    }
    // Постучаться к участникам, у которых приложение закрыто
    if (vapidKey && push && typeof push === 'object' && ['msg', 'call', 'end'].includes(push.kind) && Array.isArray(push.to)) {
      for (const t of push.to.slice(0, 20)) {
        if (!t || typeof t !== 'object' || typeof t.dev !== 'string' || !DEV_RE.test(t.dev)) continue;
        if (room.devs.has(t.dev) || !validSub(t.sub) || !pushAllowed(t.dev, push.kind)) continue;
        const note = { k: push.kind, r: roomId };
        // номер звонка (случайный) и вид звонка — чтобы кнопки «Ответить/Отклонить» в уведомлении знали, что делать
        if (typeof push.cid === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(push.cid)) note.c = push.cid;
        if (push.v === true) note.v = 1;
        sendPush(t.sub, note).catch(() => {});
      }
    }
    sendJson(res, 200, { ok: true });
  });
  req.on('error', () => {
    aborted = true;
  });
}

// Серверы для звонков. STUN помогает телефонам найти друг друга напрямую.
// Для сложных сетей можно добавить свой TURN через переменные TURN_URL, TURN_USER, TURN_PASS.
function iceServers() {
  const list = [
    { urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] },
    { urls: 'stun:stun.cloudflare.com:3478' },
  ];
  if (process.env.TURN_URL) {
    list.push({
      urls: process.env.TURN_URL.split(',').map((s) => s.trim()).filter(Boolean),
      username: process.env.TURN_USER || '',
      credential: process.env.TURN_PASS || '',
    });
  }
  return list;
}

// Проверка уведомлений: устройство просит прислать push самому себе и видит ответ push-сервиса
function handlePushTest(req, res) {
  if (!sameOrigin(req)) return sendJson(res, 403, { error: 'forbidden' });
  if (!String(req.headers['content-type'] || '').startsWith('application/json')) return sendJson(res, 415, { error: 'json only' });
  if (rateLimited(clientIp(req))) return sendJson(res, 429, { error: 'slow down' });
  let raw = '';
  req.setEncoding('utf8');
  req.on('data', (c) => {
    raw += c;
    if (raw.length > 4000) req.destroy();
  });
  req.on('end', async () => {
    let body;
    try {
      body = JSON.parse(raw);
    } catch {
      return sendJson(res, 400, { error: 'bad json' });
    }
    const r = await sendPush(body && body.sub, { k: 'test', r: '' });
    sendJson(res, 200, r);
  });
}

function handler(req, res) {
  securityHeaders(res);
  let url;
  try {
    url = new URL(req.url || '/', 'http://local');
  } catch {
    return sendJson(res, 400, { error: 'bad url' });
  }

  if (url.pathname === '/api/events' && req.method === 'GET') return handleEvents(req, res, url);
  if (url.pathname === '/api/send' && req.method === 'POST') return handleSend(req, res);
  if (url.pathname === '/api/health' && req.method === 'GET') return sendJson(res, 200, { ok: true });
  // Для Android-приложения (TWA): подтверждение, что приложение принадлежит этому сайту.
  // Содержимое кладётся в переменную окружения ASSETLINKS (JSON из PWABuilder).
  if (url.pathname === '/.well-known/assetlinks.json' && req.method === 'GET') {
    const raw = process.env.ASSETLINKS || '[]';
    try {
      return sendJson(res, 200, JSON.parse(raw));
    } catch {
      return sendJson(res, 200, []);
    }
  }
  if (url.pathname === '/api/push-test' && req.method === 'POST') return handlePushTest(req, res);
  if (url.pathname === '/api/push-key' && req.method === 'GET') {
    return sendJson(res, 200, { key: vapidKey ? VAPID_PUBLIC : null });
  }
  if (url.pathname === '/api/ice' && req.method === 'GET') return sendJson(res, 200, { iceServers: iceServers() });
  if (url.pathname === '/api/info' && req.method === 'GET') {
    // Адреса в локальной сети — только для того, кто открыл сайт на самом компьютере-сервере.
    const ip = req.socket.remoteAddress || '';
    const local = !TRUST_PROXY && (ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1');
    return sendJson(res, 200, { https: useHttps, lan: local ? lanUrls() : [] });
  }

  const entry = STATIC[url.pathname];
  if (entry && (req.method === 'GET' || req.method === 'HEAD')) {
    try {
      const body = loadStatic(entry[0]);
      res.writeHead(200, { 'Content-Type': entry[1], 'Content-Length': body.length });
      return res.end(req.method === 'HEAD' ? undefined : body);
    } catch {
      return sendJson(res, 500, { error: `файл ${entry[0]} не найден на сервере — загрузи папку public` });
    }
  }
  sendJson(res, 404, { error: 'not found' });
}

// Уборка: старые сообщения, пустые комнаты, счётчики.
setInterval(() => {
  const now = Date.now();
  for (const [id, room] of rooms) {
    while (room.history.length && now - room.history[0].ts > LIMITS.historyTtlMs) {
      room.bytes -= room.history.shift().data.length;
    }
    if (room.subs.size === 0 && room.history.length === 0) rooms.delete(id);
  }
  for (const [ip, c] of postCounters) if (now > c.reset) postCounters.delete(ip);
  for (const [k, t] of pushCooldown) if (now - t > 60_000) pushCooldown.delete(k);
}, 60_000).unref();

function createServer() {
  if (process.env.NO_HTTPS !== '1' && fs.existsSync(PFX_PATH) && fs.existsSync(PASS_PATH)) {
    try {
      const server = https.createServer(
        { pfx: fs.readFileSync(PFX_PATH), passphrase: fs.readFileSync(PASS_PATH, 'utf8').trim() },
        handler
      );
      useHttps = true;
      return server;
    } catch (e) {
      console.error('Не удалось загрузить сертификат, запускаю без HTTPS:', e.message);
    }
  }
  return http.createServer(handler);
}

const server = createServer();
server.headersTimeout = 20_000;
server.requestTimeout = 60_000;
server.keepAliveTimeout = 5_000;
server.on('clientError', (err, socket) => {
  if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
});

function lanUrls() {
  const proto = useHttps ? 'https' : 'http';
  const port = server.address() ? server.address().port : PORT;
  // Сначала настоящий Wi-Fi/Ethernet, в конце — виртуальные адаптеры и VPN (VirtualBox, Radmin, Hamachi, WSL…).
  const virtualName = /virtual|vmware|vbox|hyper-v|vethernet|wsl|docker|radmin|hamachi|zerotier|tailscale|vpn/i;
  const virtualIp = /^(192\.168\.56\.|26\.|25\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.|172\.(1[6-9]|2\d|3[01])\.)/;
  const rank = ({ name, ip }) =>
    virtualName.test(name) || virtualIp.test(ip) ? 3 : /wi-?fi|wlan|wireless|беспровод/i.test(name) ? 0 : ip.startsWith('192.168.') ? 1 : 2;
  const found = [];
  for (const [name, list] of Object.entries(os.networkInterfaces())) {
    for (const a of list || []) {
      if (a.family === 'IPv4' && !a.internal && !a.address.startsWith('169.254.')) found.push({ name, ip: a.address });
    }
  }
  return found.sort((a, b) => rank(a) - rank(b)).map(({ ip }) => `${proto}://${ip}:${port}`);
}

server.listen(PORT, HOST, () => {
  const proto = useHttps ? 'https' : 'http';
  console.log('\n  🤫  Шёпот запущен\n');
  console.log(`  На этом компьютере:  ${proto}://localhost:${PORT}`);
  for (const u of lanUrls()) console.log(`  С телефона (Wi-Fi):  ${u}`);
  if (!useHttps && !ON_HOSTING) {
    console.log('\n  ⚠  Без HTTPS шифрование в браузере работает только через localhost.');
    console.log('     Для друзей в сети запусти make-cert.ps1 и перезапусти сервер.');
  }
  console.log('\n  Сервер ничего не записывает в логи и не может читать сообщения.\n');
});

function shutdown() {
  for (const room of rooms.values()) for (const sub of room.subs) sub.end();
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 1500).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
